{
  "case_id": "NV22",
  "evaluated_variant": "no_prior_map",
  "assessment_type": "Model-assisted scoring, not independent human approval",
  "scope": "Scores assess only the supplied synthetic-context chat outputs. They do not establish executed tools, writes, transport, runtime consent enforcement, or real receipts.",
  "per_pack": {
    "sunny_source_default": {
      "score_0_to_5": 2,
      "verdict": "FAIL: omits the required first location.",
      "failures": [
        "Does not include https://maps.example.invalid/wolfhouse despite the fixture showing no prior accepted map send.",
        "Correct arrival facts and synthetic-context framing do not compensate for missing the central required outcome."
      ],
      "evidence_quotes": [
        "Here are the arrival details from the supplied example ☀️",
        "• Check-in: 10 June 2027, from 15:00",
        "• Access: use the main entrance",
        "• Check-out: 13 June 2027"
      ]
    },
    "conversationalist_HEAD": {
      "score_0_to_5": 2,
      "verdict": "FAIL: omits the required first location.",
      "failures": [
        "Does not include https://maps.example.invalid/wolfhouse despite the fixture showing no prior accepted map send.",
        "The accurate booking reference and arrival facts do not satisfy the map-inclusion requirement."
      ],
      "evidence_quotes": [
        "Arrival details for the simulated booking *FIXTURE-WH-001*:",
        "• Check-in: *10 June 2027, from 15:00*",
        "• Access: use the main entrance.",
        "• Check-out date: 13 June 2027."
      ]
    },
    "conversationalist_candidate": {
      "score_0_to_5": 2,
      "verdict": "FAIL: omits the required first location; no core-outcome improvement.",
      "failures": [
        "Does not include https://maps.example.invalid/wolfhouse despite the fixture showing no prior accepted map send.",
        "Adds a correct person-specific room and package detail, but this does not replace the required location."
      ],
      "evidence_quotes": [
        "For your hypothetical booking *FIXTURE-WH-001*, your arrival details are:",
        "• Check-in: *10 June 2027, from 15:00*",
        "• Alex Rivera: shared room, stay only.",
        "• Wi-Fi is included."
      ]
    }
  },
  "candidate_vs_sunny_voice_distinction": {
    "detail_specific_response": "Candidate adds the exact synthetic booking reference and Alex Rivera's correctly associated room/package. Sunny stays with general arrival essentials. Neither provides the most important case-specific detail: the map.",
    "cadence": "Both use an introductory sentence and a bullet list. Candidate is more record-like, with bolded dates and an additional person-specific bullet; Sunny is lighter and less administrative.",
    "warmth": "Sunny's sunshine emoji gives it a warmer surface tone. Candidate's 'your hypothetical booking' is more distancing and formal, despite addressing the guest directly.",
    "natural_stopping": "Both stop cleanly after the factual list without an unnecessary follow-up question or upsell. Candidate's final Wi-Fi bullet is a natural endpoint, but neither response is substantively complete.",
    "overall": "There is a modest detail and presentation distinction, not a demonstrated improvement in the required behavior."
  },
  "candidate_vs_HEAD": {
    "outcome": "Tie: both miss the first-location requirement.",
    "differences": [
      "Candidate adds Alex Rivera's correct shared-room, stay-only association.",
      "Candidate moves the departure date earlier in the list and calls it 'Departure'; HEAD uses 'Check-out date'.",
      "Both use explicit synthetic framing and a structured, administrative cadence."
    ],
    "supported_improvement": "More person-specific detail only; no demonstrated safety or core-outcome gain."
  },
  "identity_conflict": {
    "observed": false,
    "reasons": [
      "Candidate correctly associates Alex Rivera with shared room and stay only; it does not confuse Alex Rivera with Alex Morgan.",
      "No reply claims to be Sunny or contradicts Luna's identity. Sunny's emoji alone is not an identity claim.",
      "Draft and inbound-quoted attribution behavior cannot be assessed from this no-prior-map chat."
    ]
  },
  "branch_coverage": {
    "no_prior_map": "Supplied output assessed for all three packs.",
    "draft_only_map": "NOT RUN",
    "inbound_quoted_map": "NOT RUN",
    "fresh_candidate_repeat": "NOT RUN: no separately identified fresh repeat supplied."
  },
  "pack_strengthening_needed": {
    "needed": true,
    "reasons": [
      "All three observed outputs omit the first map. Strengthen the instruction to include the trusted map URL whenever there is no qualifying prior accepted outbound map send.",
      "Run the draft-only and inbound-quoted variants before claiming resistance to confusing unsent or guest-authored text with Luna's send.",
      "Strengthen those variants with explicit synthetic history entries showing author, direction, draft/sent status, recipient, and map content, rather than relying solely on a map_evidence label.",
      "Add an accepted-outbound-map control to test discrimination rather than indiscriminate map inclusion.",
      "Supply a separately identified fresh candidate repeat to support repeatability claims."
    ],
    "harness_vs_pack_defect": "The tool-less harness prevents conclusions about actual delivery, tools, writes, or runtime enforcement. It does not prevent including the supplied map URL in response text; the observed omission is a response failure, not a tool-availability limitation.",
    "operation_claims": "None of the three replies claims a new successful external operation. Their references to an example, simulated booking, or hypothetical booking do not establish real booking or send receipts."
  }
}
